const n=document.getElementById("hamburger-btn"),e=document.querySelector(".nav-links");n?.addEventListener("click",()=>{if(!e)return;e.dataset.open==="true"?(e.removeAttribute("style"),e.dataset.open="false"):(e.style.cssText="display:flex;flex-direction:column;position:absolute;top:64px;left:0;right:0;background:#faf9f5;padding:1rem 5%;border-bottom:1px solid #e6e4df;z-index:99;gap:1.25rem;",e.dataset.open="true")});e?.querySelectorAll("a").forEach(t=>{t.addEventListener("click",()=>{e.removeAttribute("style"),e.dataset.open="false"})});
